Biographics Legacy outro typewriter. 9s, 1920x1080, SILENT. Fix: no dynamic width measurement — use hardcoded widths. No array targets in GSAP — each element gets its own tween.

```html
<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<link href="https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,400;0,700;1,400;1,700&display=swap" rel="stylesheet">
<style>
*{margin:0;padding:0;box-sizing:border-box;}
body,#scene{width:1920px;height:1080px;overflow:hidden;background:#000;}
#scene{position:relative;display:flex;align-items:center;justify-content:center;}

#bg{
  position:absolute;top:0;left:0;width:100%;height:100%;
  object-fit:cover;z-index:1;opacity:0;
}
#overlay{
  position:absolute;top:0;left:0;width:100%;height:100%;z-index:2;
  background:linear-gradient(to top,rgba(0,0,0,0.88) 0%,rgba(0,0,0,0.40) 55%,rgba(0,0,0,0.18) 100%);
}
#fade{
  position:absolute;top:0;left:0;width:100%;height:100%;
  z-index:50;background:#000;opacity:0;pointer-events:none;
}

#content{
  position:relative;z-index:10;
  display:flex;flex-direction:column;align-items:center;
}

/* Rules */
#rule-top,#rule-bot{
  height:1px;width:0;
  background:linear-gradient(to right,transparent,#8b2e2e 20%,#8b2e2e 80%,transparent);
}
#rule-top{margin-bottom:32px;}
#rule-bot{margin-top:32px;margin-bottom:44px;}

/* Text lines — overflow hidden, hardcoded max-width container */
/* Font: Playfair Display italic 34px, letter-spacing 0.04em
   Line 1: "From London fog to Strange dimensions —"  ~900px at this size
   Line 2: "and back to the stage where it began."    ~820px
   History: "History, one life at a time."            ~560px at 20px
   All widths set generously to ensure NO clipping */
.tw{
  overflow:hidden;
  white-space:nowrap;
  width:0;  /* animated to hardcoded target */
}
#line1{
  font-family:'Playfair Display',Georgia,serif;
  font-size:34px;font-style:italic;font-weight:400;
  color:rgba(220,208,192,0.90);letter-spacing:0.04em;line-height:1.4;
}
#line2{
  font-family:'Playfair Display',Georgia,serif;
  font-size:34px;font-style:italic;font-weight:400;
  color:rgba(220,208,192,0.90);letter-spacing:0.04em;line-height:1.4;
  margin-top:4px;
}
#history{
  font-family:'Playfair Display',Georgia,serif;
  font-size:20px;font-weight:700;
  color:#8b2e2e;letter-spacing:0.38em;text-transform:uppercase;
}
</style>
</head>
<body>
<div id="scene">
  <video id="bg" autoplay muted loop playsinline>
    <source src="{{bgVid}}" type="video/mp4">
  </video>
  <div id="overlay"></div>
  <div id="fade"></div>

  <div id="content">
    <div id="rule-top"></div>
    <div id="line1" class="tw">From London fog to Strange dimensions —</div>
    <div id="line2" class="tw">and back to the stage where it began.</div>
    <div id="rule-bot"></div>
    <div id="history" class="tw">History, one life at a time.</div>
  </div>
</div>

<script src="vendor/gsap.min.js"></script>
<script>
window.addEventListener('DOMContentLoaded', function(){

  /* Hardcoded target widths — measured offline at the specified font/size.
     Values are intentionally generous (+60px) so the last character is NEVER clipped. */
  var W1 = 960;   /* line1 full width */
  var W2 = 880;   /* line2 full width */
  var WH = 620;   /* history full width */
  var WR = 500;   /* rule width */

  var tl = gsap.timeline();

  /* BG fade in */
  tl.to('#bg',       { opacity:0.50, duration:0.9, ease:'power2.out' }, 0.0);

  /* top rule */
  tl.to('#rule-top', { width:WR, duration:0.45, ease:'power2.out' }, 0.6);

  /* line 1 typewriter */
  tl.to('#line1',    { width:W1, duration:1.3,  ease:'none' }, 1.1);

  /* line 2 typewriter */
  tl.to('#line2',    { width:W2, duration:1.2,  ease:'none' }, 2.5);

  /* bottom rule */
  tl.to('#rule-bot', { width:WR, duration:0.4,  ease:'power2.out' }, 3.8);

  /* history typewriter */
  tl.to('#history',  { width:WH, duration:1.1,  ease:'none' }, 4.4);

  /* ── EXIT — each element individually, no arrays ── */
  tl.to('#history',  { width:0, duration:0.55, ease:'none' }, 6.4);
  tl.to('#rule-bot', { width:0, duration:0.3,  ease:'power2.in' }, 6.7);
  tl.to('#rule-top', { width:0, duration:0.3,  ease:'power2.in' }, 6.75);
  tl.to('#line2',    { width:0, duration:0.5,  ease:'none' }, 6.75);
  tl.to('#line1',    { width:0, duration:0.5,  ease:'none' }, 6.8);

  /* fade to black */
  tl.to('#fade',     { opacity:1, duration:1.4, ease:'power2.inOut' }, 7.5);
});
</script>
</body>
</html>
